import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"蜀道难","description":"","frontmatter":{"title":"蜀道难","date":"2026-11-27T00:00:00.000Z","seq":22,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 乐府》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"李白","source_book":"唐诗三百首","prev":{"text":"长干行·其一","link":"/blogs/唐诗三百首·乐府/长干行·其一.html"},"next":{"text":"子夜吴歌·春歌","link":"/blogs/唐诗三百首·乐府/子夜吴歌·春歌.html"}},"headers":[],"relativePath":"blogs/唐诗三百首·乐府/蜀道难.md","filePath":"blogs/唐诗三百首·乐府/蜀道难.md"}'),o={name:"blogs/唐诗三百首·乐府/蜀道难.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="蜀道难" tabindex="-1">蜀道难 <a class="header-anchor" href="#蜀道难" aria-label="Permalink to &quot;蜀道难&quot;">​</a></h1><p class="poem-meta">唐 · 李白　·　乐府</p><div class="poem"><p class="poem-stanza">噫吁嚱，危乎高哉！</p><p class="poem-stanza">蜀道之难，难于上青天！</p><p class="poem-stanza">蚕丛及鱼凫，开国何茫然！</p><p class="poem-stanza">尔来四万八千岁，不与秦塞通人烟。</p><p class="poem-stanza">西当太白有鸟道，可以横绝峨眉巅。</p><p class="poem-stanza">地崩山摧壮士死，然后天梯石栈相钩连。</p><p class="poem-stanza">上有六龙回日之高标，下有冲波逆折之回川。</p><p class="poem-stanza">黄鹤之飞尚不得过，猿猱欲度愁攀援。(攀援 一作：攀缘)</p><p class="poem-stanza">青泥何盘盘，百步九折萦岩峦。</p><p class="poem-stanza">扪参历井仰胁息，以手抚膺坐长叹。</p><p class="poem-stanza">问君西游何时还？畏途巉岩不可攀。</p><p class="poem-stanza">但见悲鸟号古木，雄飞雌从绕林间。</p><p class="poem-stanza">又闻子规啼夜月，愁空山。</p><p class="poem-stanza">蜀道之难,难于上青天，使人听此凋朱颜！</p><p class="poem-stanza">连峰去天不盈尺，枯松倒挂倚绝壁。</p><p class="poem-stanza">飞湍瀑流争喧豗，砯崖转石万壑雷。</p><p class="poem-stanza">其险也如此，嗟尔远道之人胡为乎来哉！(也如此 一作：也若此)</p><p class="poem-stanza">剑阁峥嵘而崔嵬，一夫当关，万夫莫开。</p><p class="poem-stanza">所守或匪亲，化为狼与豺。</p><p class="poem-stanza">朝避猛虎，夕避长蛇；磨牙吮血，杀人如麻。</p><p class="poem-stanza">锦城虽云乐，不如早还家。</p><p class="poem-stanza">蜀道之难,难于上青天，侧身西望长咨嗟！</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
